+/**
+ * Make a filesystem-safe slug for strategy ids.
+ * 
+ * @param {string[]} strategyIds
+ * @returns {string}
+ */
+function makeStrategySlug(strategyIds) {
+  const raw = strategyIds.join("+");
+  const safe = raw.replace(/[^a-zA-Z0-9._+-]+/g, "_");
+
+  // Avoid super-long folder names; keep readable prefix + stable hash suffix.
+  if (safe.length <= 80) return safe;
+  return `${safe.slice(0, 60)}__${hashString(raw)}`;
+}
+
+/**
+ * Ensure a directory path is unique. If it already exists, append _01, _02, ...
+ * 
+ * @param {string} baseDir
+ * @returns {string}
